COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
20260419072141	{"-- =========================================================\n-- Course units + scoping to institution (migration)\n-- =========================================================\n\n-- 1) Course units table (per institution)\ncreate table if not exists public.course_units (\n  id uuid primary key default gen_random_uuid(),\n  institution_id text not null references public.institutions(id) on delete cascade,\n  name text not null,\n  code text,\n  created_at timestamptz default now()\n)","-- 2) Enable RLS\nalter table public.course_units enable row level security","-- 3) Policy: institution admin manages their units\ndrop policy if exists \\"Institution admin manages their units\\"\non public.course_units","create policy \\"Institution admin manages their units\\"\non public.course_units\nfor all\nusing (\n  institution_id = (\n    select p.institution_id\n    from public.profiles p\n    where p.id = auth.uid()\n  )\n)\nwith check (\n  institution_id = (\n    select p.institution_id\n    from public.profiles p\n    where p.id = auth.uid()\n  )\n)","-- 4) Scope coordinators to a unit\nalter table public.profiles\n  add column if not exists course_unit_id uuid\n  references public.course_units(id) on delete set null","-- 5) Scope attendance records to a unit\nalter table public.attendance_records\n  add column if not exists course_unit_id uuid\n  references public.course_units(id) on delete set null"}	new-migration
20260419102407	{"-- 1. Add a temporary column (using text[] to match your current logic, or uuid[] if preferred)\nALTER TABLE profiles ADD COLUMN course_unit_ids_new text[]","-- 2. Convert existing single values to arrays\n-- Removed the '' comparison; NULL check is sufficient for UUID/Reference fields\nUPDATE profiles\nSET course_unit_ids_new = ARRAY[course_unit_id::text]\nWHERE course_unit_id IS NOT NULL \n  AND role = 'coordinator'","-- 3. Drop the old column\nALTER TABLE profiles DROP COLUMN course_unit_id","-- 4. Rename the new column to the original name\nALTER TABLE profiles RENAME COLUMN course_unit_ids_new TO course_unit_id","-- 5. Add documentation\nCOMMENT ON COLUMN profiles.course_unit_id IS 'Array of course unit IDs assigned to this coordinator'"}	profiles_alter
20260421153904	{"CREATE POLICY \\"Attendance readable in institution\\"\nON public.attendance_records\nFOR SELECT TO authenticated\nUSING (\n  institution_id = (\n    SELECT p.institution_id\n    FROM public.profiles p\n    WHERE p.id = auth.uid()\n  )\n  AND\n  (\n    -- Admins can read all attendance in the institution\n    EXISTS (\n      SELECT 1\n      FROM public.profiles p\n      WHERE p.id = auth.uid()\n        AND (p.is_admin = true OR p.is_super_admin = true)\n    )\n    -- Coordinators read only their assigned course_unit_id(s)\n    OR course_unit_id = ANY (\n      (\n        SELECT p.course_unit_id\n        FROM public.profiles p\n        WHERE p.id = auth.uid()\n      )::uuid[]\n    )\n  )\n)"}	policies_fix
20260506122750	{"-- ============================================================\n-- FaceAttend: Audit Logs Migration (FIXED)\n-- institutions.id is TEXT, profiles.id is UUID\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS audit_logs (\n    id              UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    institution_id  TEXT REFERENCES institutions(id) ON DELETE SET NULL,  -- TEXT to match institutions.id\n    actor_id        UUID REFERENCES profiles(id) ON DELETE SET NULL,       -- UUID to match profiles.id\n    actor_email     TEXT,\n    action          TEXT NOT NULL,\n    resource_type   TEXT,\n    resource_id     TEXT,\n    metadata        JSONB DEFAULT '{}',\n    ip_address      TEXT,\n    created_at      TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS audit_logs_institution_id_idx ON audit_logs(institution_id)","CREATE INDEX IF NOT EXISTS audit_logs_created_at_idx     ON audit_logs(created_at DESC)","CREATE INDEX IF NOT EXISTS audit_logs_action_idx         ON audit_logs(action)","CREATE INDEX IF NOT EXISTS audit_logs_actor_id_idx       ON audit_logs(actor_id)","-- RLS\nALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"admins_see_own_institution_logs\\"\nON audit_logs FOR SELECT\nUSING (\n    auth.uid() IN (\n        SELECT id FROM profiles\n        WHERE institution_id = audit_logs.institution_id\n          AND is_admin = TRUE\n    )\n)","CREATE POLICY \\"super_admins_see_all_logs\\"\nON audit_logs FOR SELECT\nUSING (\n    auth.uid() IN (\n        SELECT id FROM profiles\n        WHERE is_super_admin = TRUE AND is_admin = TRUE\n    )\n)","CREATE POLICY \\"service_role_insert\\"\nON audit_logs FOR INSERT\nWITH CHECK (TRUE)","-- ============================================================\n-- known_devices table\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS known_devices (\n    id              UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    actor_id        UUID REFERENCES profiles(id) ON DELETE CASCADE,\n    ip_address      TEXT,\n    device_info     TEXT,\n    first_seen_at   TIMESTAMPTZ DEFAULT NOW(),\n    last_seen_at    TIMESTAMPTZ DEFAULT NOW(),\n    UNIQUE(actor_id, ip_address)\n)","CREATE INDEX IF NOT EXISTS known_devices_actor_id_idx ON known_devices(actor_id)"}	audit_logs
